# region: sift
def sift(raw):
    out = []
    for tok in raw[1:]:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: intake
def intake(xs, offset=1):
    return [v + offset for v in xs]

# region: emit
def emit(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: render
def render(xs):
    d = {}
    for v in xs:
        d[v % 3] = d.get(v % 3, 0) + 1
    return {'n': len(xs), 'tally': sorted(d.items())}

# region: gather
def gather(summary, name='gamma'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return gather(render(emit(intake(sift(raw)))))

