        self.assertEqual(run(['3', '1', '2']), {'n': 3, 'tally': [(0.0, 2), (1.0, 1)], 'label': 'GAMMA'})
    def test_case_01(self):
        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 3, 'tally': [(0.0, 1), (2.0, 2)], 'label': 'GAMMA'})
    def test_case_02(self):
        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 3, 'tally': [(0.0, 1), (2.0, 2)], 'label': 'GAMMA'})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 0, 'tally': [], 'label': 'EMPTY'})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'tally': [(1.0, 2), (2.0, 1)], 'label': 'GAMMA'})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 1, 'tally': [(1.0, 1)], 'label': 'GAMMA'})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'tally': [(0.0, 1), (1.0, 2), (2.0, 1)], 'label': 'GAMMA'})
